public void CalcTot()
        {
            try
            {
                double total = 0;
                int count = 0;

                foreach (var row in _itemsSource)
                {
                    if (!string.IsNullOrEmpty(row.ItemName))
                    {
                        total += row.Total;
                        count++;
                    }
                }

                txtSumVal.Text = $"{Math.Round(total, 2):N2}";
                txtTirmsNo.Text = count.ToString();
                txtTotQuan.Text = count.ToString();
            }
            catch { }
        }

