                    $"SELECT units.name AS UnitName FROM items " +
                    $"LEFT JOIN units ON items.unit=units.Id " +
                    $"WHERE items.id={itemId}", conn);
                var dt = new DataTable();
                adapter.Fill(dt);
                return dt.Rows.Count > 0 ? dt.Rows[0]["UnitName"]?.ToString() ?? "" : "";
